def calculate_factorial(n):
    if not isinstance(n, int) or n < 0:
        with open("error.log", "a") as f:
            f.write(f"Invalid input: {n}. n must be a non-negative integer.\n")
        raise ValueError("n must be a non-negative integer.")

    if n == 0:
        with open("factorial_results.txt", "a") as f:
            f.write(f"Factorial of {n} is 1\n")
        return 1
    else:
        result = 1
        for i in range(1, n + 1):
            result *= i
        with open("factorial_results.txt", "a") as f:
            f.write(f"Factorial of {n} is {result}\n")
        with open("last_calculation.txt", "w") as f:
            f.write(f"The last factorial calculated was for {n} and the result was {result}.\n")
        return result

if __name__ == "__main__":
    with open("input.txt", "r") as input_file:
        numbers_str = input_file.read().strip().split(',')

    for num_str in numbers_str:
        try:
            num = int(num_str.strip())
            calculate_factorial(num)
        except ValueError as e:
            print(f"Skipping invalid input: {num_str} - {e}")

import os
import sys


def find_max(numbers):
    """Return the largest value in a non-empty list of integers."""
    largest = numbers[0]
    for value in numbers[1:]:
        if value > largest:
            largest = value
    return largest


def load_manifest(path):
    """Read a manifest file listing one dataset path per line."""
    paths = []
    with open(path, "r", encoding="utf-8") as manifest:
        for line in manifest:
            entry = line.strip()
            if entry and not entry.startswith("#"):
                paths.append(entry)
    return paths


def parse_numbers(path):
    """Read whitespace/comma separated integers from a dataset file."""
    numbers = []
    with open(path, "r", encoding="utf-8") as dataset:
        for lineno, line in enumerate(dataset, start=1):
            for token in line.replace(",", " ").split():
                try:
                    numbers.append(int(token))
                except ValueError:
                    raise ValueError(
                        "%s line %d: %r is not an integer" % (path, lineno, token)
                    )
    if not numbers:
        raise ValueError("%s contains no integers" % path)
    return numbers


def previous_best(path):
    """Return the largest maximum recorded in the history log, or None."""
    seen = []
    try:
        with open(path, "r", encoding="utf-8") as history:
            for line in history:
                _, _, value = line.rpartition("->")
                if value.strip():
                    seen.append(int(value))
    except FileNotFoundError:
        return None
    return find_max(seen) if seen else None


def write_report(path, results):
    """Write a per-dataset maximum report and return the overall maximum."""
    overall = find_max([maximum for _name, _count, maximum in results])
    with open(path, "w", encoding="utf-8") as report:
        report.write("dataset\tcount\tmaximum\n")
        for name, count, maximum in results:
            report.write("%s\t%d\t%d\n" % (name, count, maximum))
        report.write("overall maximum: %d\n" % overall)
    return overall


def append_history(path, label, overall):
    with open(path, "a", encoding="utf-8") as history:
        history.write("%s -> %d\n" % (label, overall))


def main(argv):
    dataset_paths = argv[1:]
    if not dataset_paths:
        dataset_paths = load_manifest("datasets.txt")

    results = []
    for path in dataset_paths:
        numbers = parse_numbers(path)
        results.append((os.path.basename(path), len(numbers), find_max(numbers)))

    earlier = previous_best("max_history.log")
    overall = write_report("max_report.tsv", results)
    append_history("max_history.log", ",".join(name for name, _c, _m in results), overall)

    for name, count, maximum in results:
        print("%-20s %4d values, max = %d" % (name, count, maximum))
    print("overall maximum: %d" % overall)
    if earlier is not None:
        print("previous recorded maximum: %d" % earlier)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

