import json
import sys
from datetime import datetime


def merge_dictionaries(dict1, dict2):
    merged = dict(dict1)
    for key, value in dict2.items():
        merged[key] = value
    return merged


def load_config(path):
    with open(path, encoding="utf-8") as f:
        data = json.load(f)
    if not isinstance(data, dict):
        raise ValueError("%s does not contain a JSON object" % path)
    return data


def read_manifest(path):
    paths = []
    with open(path, encoding="utf-8") as f:
        for line in f:
            entry = line.strip()
            if entry and not entry.startswith("#"):
                paths.append(entry)
    if not paths:
        raise ValueError("%s lists no configuration files" % path)
    return paths


def merge_config_files(paths):
    merged = {}
    for path in paths:
        merged = merge_dictionaries(merged, load_config(path))
    return merged


def describe_overrides(base, override):
    lines = []
    for key in sorted(override):
        if key in base:
            lines.append("%s: %r -> %r" % (key, base[key], override[key]))
        else:
            lines.append("%s: added %r" % (key, override[key]))
    for key in sorted(set(base) - set(override)):
        lines.append("%s: kept %r" % (key, base[key]))
    return lines


def save_config(path, config):
    with open(path, "w", encoding="utf-8") as f:
        json.dump(config, f, indent=2, sort_keys=True)
        f.write("\n")


def write_report(path, base, override, merged):
    with open(path, "w", encoding="utf-8") as f:
        f.write("keys in base: %d\n" % len(base))
        f.write("keys in override: %d\n" % len(override))
        f.write("keys in result: %d\n" % len(merged))
        for line in describe_overrides(base, override):
            f.write("  " + line + "\n")


def append_log(path, sources, target):
    stamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    with open(path, "a", encoding="utf-8") as f:
        f.write("%s merged %s into %s\n" % (stamp, ", ".join(sources), target))


def main(argv):
    args = argv[1:]
    if len(args) == 2 and args[0] == "--manifest":
        sources = read_manifest(args[1])
    elif len(args) >= 2:
        sources = args
    else:
        print("usage: merge.py base.json override.json [more.json ...]")
        print("       merge.py --manifest configs.txt")
        return 1
    base = load_config(sources[0])
    override = merge_config_files(sources[1:])
    merged = merge_dictionaries(base, override)
    save_config("merged.json", merged)
    write_report("merged.report.txt", base, override, merged)
    append_log("merge.log", sources, "merged.json")
    print("wrote merged.json with %d keys" % len(merged))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

