def read_requests(path):
    """Read one requested value of n per line, ignoring blanks and comments."""
    values = []
    with open(path, encoding="utf-8") as f:
        for lineno, line in enumerate(f, 1):
            text = line.strip()
            if not text or text.startswith("#"):
                continue
            try:
                values.append(int(text))
            except ValueError:
                raise ValueError("%s:%d: not an integer: %r" % (path, lineno, text))
    return values


def load_cache(path):
    """Load previously computed square lists, keyed by n."""
    try:
        with open(path, encoding="utf-8") as f:
            stored = json.load(f)
    except FileNotFoundError:
        return {}
    return {int(key): value for key, value in stored.items()}


def save_cache(path, cache):
