import sys


def parse_csv_line(line):
    """Split a single CSV line into its comma-separated values."""
    return line.rstrip("\r\n").split(",")


def read_csv_file(path):
    """Read a CSV file and return a list of (line number, values) pairs."""
    records = []
    with open(path, "r", encoding="utf-8") as f:
        for number, line in enumerate(f, start=1):
            if line.strip():
                records.append((number, parse_csv_line(line)))
    return records


def load_schema(path):
    """Read the expected column names from the first useful line of a schema file."""
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            if line.strip():
                return parse_csv_line(line)
    raise ValueError("schema file %s contains no column names" % path)


def write_tsv(path, columns, records):
    """Write the records matching the schema width as a tab separated table."""
    written = 0
    with open(path, "w", encoding="utf-8") as f:
        f.write("\t".join(columns) + "\n")
        for _, values in records:
            if len(values) == len(columns):
                f.write("\t".join(value.strip() for value in values) + "\n")
                written += 1
    return written


def write_rejects(path, columns, records):
    """Write back the records whose field count differs from the schema."""
    rejected = 0
    with open(path, "w", encoding="utf-8") as f:
        for number, values in records:
            if len(values) != len(columns):
                f.write("%d,%s\n" % (number, ",".join(values)))
                rejected += 1
    return rejected


def validate_records(records, columns):
    """Compare each record against the schema, returning a list of problems."""
    problems = []
    width = len(columns)
    for number, values in records:
        if len(values) != width:
            problems.append(
                "line %d: expected %d fields, found %d" % (number, width, len(values))
            )
            continue
        for name, value in zip(columns, values):
            if not value.strip():
                problems.append("line %d: empty value for column %r" % (number, name))
    return problems


def write_report(path, source, columns, records, written, rejected, problems):
    """Summarise the conversion so the run can be inspected afterwards."""
    with open(path, "w", encoding="utf-8") as f:
        f.write("source: %s\n" % source)
        f.write("columns: %s\n" % ", ".join(columns))
        f.write("records read: %d\n" % len(records))
        f.write("records written: %d\n" % written)
        f.write("records rejected: %d\n" % rejected)
        for problem in problems:
            f.write("  %s\n" % problem)


def main(argv):
    if len(argv) != 5:
        print("usage: convert data.csv schema.csv out.tsv rejects.csv report.txt")
        return 2
    data_path, schema_path, tsv_path, rejects_path, report_path = argv
    columns = load_schema(schema_path)
    records = read_csv_file(data_path)
    problems = validate_records(records, columns)
    written = write_tsv(tsv_path, columns, records)
    rejected = write_rejects(rejects_path, columns, records)
    write_report(report_path, data_path, columns, records, written, rejected, problems)
    print("wrote %d of %d records to %s" % (written, len(records), tsv_path))
    return 1 if problems else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

