import sys


def reverse_words(sentence):
    """Return `sentence` with the order of its words reversed."""
    return ' '.join(reversed(sentence.split()))


def parse_manifest_line(line):
    """Turn 'source.txt -> target.txt' into a (source, target) pair."""
    if '->' not in line:
        raise ValueError('manifest line must look like "source -> target": %r' % line)
    source, target = line.split('->', 1)
    source, target = source.strip(), target.strip()
    if not source or not target:
        raise ValueError('manifest line has an empty path: %r' % line)
    return source, target


def load_manifest(path):
    """Read a manifest of "source -> target" jobs, ignoring blanks and comments."""
    jobs = []
    with open(path, encoding='utf-8') as manifest:
        for raw in manifest:
            line = raw.strip()
            if line and not line.startswith('#'):
                jobs.append(parse_manifest_line(line))
    return jobs


def reverse_file(source, target):
    """Write every line of `source` to `target` with its words reversed."""
    with open(source, encoding='utf-8') as infile:
        reversed_lines = [reverse_words(line) for line in infile]
    with open(target, 'w', encoding='utf-8') as outfile:
        for line in reversed_lines:
            outfile.write(line + '\n')
    return len(reversed_lines)


def format_report(rows):
    width = max((len(source) for source, _, _ in rows), default=6)
    lines = ['%-*s  %s  %s' % (width, 'SOURCE', 'LINES', 'TARGET')]
    for source, target, count in rows:
        lines.append('%-*s  %5d  %s' % (width, source, count, target))
    lines.append('total lines reversed: %d' % sum(count for _, _, count in rows))
    return '\n'.join(lines)


def write_report(path, rows):
    with open(path, 'w', encoding='utf-8') as report:
        report.write(format_report(rows) + '\n')


def write_errors(path, failures):
    """Record the jobs that could not be processed, one per line."""
    with open(path, 'w', encoding='utf-8') as log:
        for source, message in failures:
            log.write('%s: %s\n' % (source, message))
        if not failures:
            log.write('no errors\n')


def main(argv):
    if len(argv) != 4:
        print('usage: %s MANIFEST REPORT ERRORS' % argv[0], file=sys.stderr)
        return 2
    manifest_path, report_path, errors_path = argv[1], argv[2], argv[3]
    rows, failures = [], []
    for source, target in load_manifest(manifest_path):
        try:
            rows.append((source, target, reverse_file(source, target)))
        except OSError as exc:
            failures.append((source, exc.strerror or str(exc)))
    write_report(report_path, rows)
    write_errors(errors_path, failures)
    print('processed %d file(s), %d failure(s)' % (len(rows), len(failures)))
    return 1 if failures else 0


if __name__ == '__main__':
    sys.exit(main(sys.argv))

