import sys


def decimal_to_binary(decimal_int):
    if not isinstance(decimal_int, int) or isinstance(decimal_int, bool):
        raise TypeError("decimal_to_binary expects an int")
    if decimal_int < 0:
        raise ValueError("decimal_to_binary expects a non-negative int")
    if decimal_int == 0:
        return '0'
    digits = []
    while decimal_int > 0:
        digits.append(str(decimal_int % 2))
        decimal_int //= 2
    return ''.join(reversed(digits))


def read_decimals(path):
    values = []
    rejected = []
    with open(path, encoding="utf-8") as source:
        for line_number, raw in enumerate(source, start=1):
            token = raw.strip()
            if not token:
                continue
            try:
                number = int(token)
            except ValueError:
                rejected.append((line_number, token))
                continue
            if number < 0:
                rejected.append((line_number, token))
            else:
                values.append(number)
    return values, rejected


def write_binaries(path, values):
    with open(path, "w", encoding="utf-8") as target:
        for number in values:
            target.write("{} {}\n".format(number, decimal_to_binary(number)))


def write_rejects(path, rejected):
    with open(path, "w", encoding="utf-8") as target:
        for line_number, token in rejected:
            target.write("line {}: {!r} is not a non-negative integer\n".format(line_number, token))


def verify_output(path):
    mismatches = []
    with open(path, encoding="utf-8") as produced:
        for raw in produced:
            decimal_text, binary_text = raw.split()
            if int(binary_text, 2) != int(decimal_text):
                mismatches.append(raw.strip())
    return mismatches


def write_report(path, values, rejected, mismatches):
    widest = max((len(decimal_to_binary(n)) for n in values), default=0)
    with open(path, "w", encoding="utf-8") as report:
        report.write("converted: {}\n".format(len(values)))
        report.write("rejected: {}\n".format(len(rejected)))
        report.write("longest binary string: {} bits\n".format(widest))
        report.write("verification mismatches: {}\n".format(len(mismatches)))


def main(argv):
    if len(argv) != 2:
        print("usage: {} INPUT_FILE".format(argv[0]))
        return 2
    values, rejected = read_decimals(argv[1])
    write_binaries("binaries.txt", values)
    write_rejects("rejected.txt", rejected)
    mismatches = verify_output("binaries.txt")
    write_report("report.txt", values, rejected, mismatches)
    print("wrote {} conversions to binaries.txt".format(len(values)))
    return 1 if mismatches else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

