import os
import sys


def is_valid_parentheses(s):
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    for ch in s:
        if ch in pairs.values():
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
        else:
            raise ValueError("unsupported character: %r" % ch)
    return not stack


def load_cases(path):
    cases = []
    with open(path, encoding="utf-8") as f:
        for lineno, line in enumerate(f, start=1):
            text = line.strip()
            if text:
                cases.append((lineno, text))
    return cases


def evaluate(cases):
    results = []
    for lineno, text in cases:
        try:
            verdict = is_valid_parentheses(text)
        except ValueError as exc:
            results.append((lineno, text, None, str(exc)))
        else:
            results.append((lineno, text, verdict, ""))
    return results


def write_report(path, source, results):
    with open(path, "w", encoding="utf-8") as f:
        f.write("report for %s\n" % source)
        for lineno, text, verdict, problem in results:
            if verdict is None:
                f.write("%4d  %-20s SKIPPED (%s)\n" % (lineno, text, problem))
            else:
                label = "VALID" if verdict else "INVALID"
                f.write("%4d  %-20s %s\n" % (lineno, text, label))


def write_invalid(path, results):
    with open(path, "w", encoding="utf-8") as f:
        for _lineno, text, verdict, _problem in results:
            if verdict is False:
                f.write(text + "\n")


def append_summary(path, source, results):
    valid = sum(1 for r in results if r[2] is True)
    invalid = sum(1 for r in results if r[2] is False)
    skipped = sum(1 for r in results if r[2] is None)
    with open(path, "a", encoding="utf-8") as f:
        f.write("%s: valid=%d invalid=%d skipped=%d\n"
                % (source, valid, invalid, skipped))


def show(path):
    with open(path, encoding="utf-8") as f:
        sys.stdout.write(f.read())


def main(argv):
    if len(argv) < 2:
        sys.stderr.write("usage: %s FILE [FILE ...]\n" % argv[0])
        return 1
    for source in argv[1:]:
        stem = os.path.splitext(os.path.basename(source))[0]
        results = evaluate(load_cases(source))
        report = stem + "_report.txt"
        write_report(report, source, results)
        write_invalid(stem + "_invalid.txt", results)
        append_summary("bracket_summary.log", source, results)
        show(report)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

