import csv
import sys
from datetime import datetime


def load_inventory(path):
    inventory = {}
    with open(path, newline="", encoding="utf-8") as f:
        for row in csv.reader(f):
            if not row:
                continue
            name = row[0].strip()
            inventory[name] = int(row[1].strip())
    return inventory


def load_items(path):
    items = []
    with open(path, encoding="utf-8") as f:
        for line in f:
            name = line.strip()
            if name and name not in items:
                items.append(name)
    return items


def load_thresholds(path):
    thresholds = {}
    with open(path, newline="", encoding="utf-8") as f:
        for row in csv.reader(f):
            if len(row) >= 2:
                thresholds[row[0].strip()] = int(row[1].strip())
    return thresholds


def check_stock(inventory, items_to_check):
    stock_levels = {}
    for item in items_to_check:
        stock_levels[item] = inventory.get(item, 0)
    return stock_levels


def format_report(stock_levels, thresholds):
    width = max((len(name) for name in stock_levels), default=4)
    lines = []
    for name, quantity in stock_levels.items():
        limit = thresholds.get(name, 0)
        flag = "LOW" if quantity <= limit else "OK"
        lines.append("{:<{w}}  {:>6}  {}".format(name, quantity, flag, w=width))
    return lines


def write_report(path, lines):
    with open(path, "w", encoding="utf-8") as f:
        f.write("stock report\n")
        for line in lines:
            f.write(line + "\n")


def append_history(path, stock_levels):
    stamp = datetime.now().isoformat(timespec="seconds")
    with open(path, "a", encoding="utf-8") as f:
        for name, quantity in stock_levels.items():
            f.write("{}\t{}\t{}\n".format(stamp, name, quantity))


def main(argv):
    if len(argv) != 5:
        print("usage: stock.py inventory.csv items.txt thresholds.csv report.txt")
        return 1
    inventory = load_inventory(argv[1])
    items = load_items(argv[2])
    thresholds = load_thresholds(argv[3])
    stock_levels = check_stock(inventory, items)
    write_report(argv[4], format_report(stock_levels, thresholds))
    append_history(argv[4] + ".history", stock_levels)
    missing = [name for name, qty in stock_levels.items() if qty == 0]
    print("checked {} items, {} out of stock".format(len(stock_levels), len(missing)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

