import json
import sys
from collections import Counter


def parse_log_line(log_line):
    parts = log_line.split(' - ', 2)
    if len(parts) < 3:
        raise ValueError('malformed log line: %r' % log_line)
    timestamp, level, message = parts
    return {'timestamp': timestamp.strip(), 'level': level.strip().upper(),
            'message': message.strip()}


def read_log_file(path):
    records = []
    with open(path, encoding='utf-8') as f:
        for lineno, line in enumerate(f, start=1):
            line = line.strip()
            if not line:
                continue
            try:
                records.append(parse_log_line(line))
            except ValueError:
                records.append({'timestamp': '', 'level': 'UNPARSED',
                                'message': 'line %d: %s' % (lineno, line)})
    return records


def load_levels(path):
    levels = set()
    with open(path, encoding='utf-8') as f:
        for line in f:
            name = line.strip().upper()
            if name:
                levels.add(name)
    return levels


def write_json(records, path):
    with open(path, 'w', encoding='utf-8') as f:
        json.dump(records, f, indent=2)
        f.write('\n')


def write_report(records, path, levels):
    counts = Counter(record['level'] for record in records)
    with open(path, 'w', encoding='utf-8') as f:
        f.write('total records: %d\n' % len(records))
        for level in sorted(counts):
            f.write('%-8s %d\n' % (level, counts[level]))
        for record in records:
            if record['level'] in levels:
                f.write('%s | %s\n' % (record['timestamp'], record['message']))


def write_unparsed(records, path):
    bad = [record for record in records if record['level'] == 'UNPARSED']
    with open(path, 'w', encoding='utf-8') as f:
        for record in bad:
            f.write(record['message'] + '\n')
    return len(bad)


def main(argv):
    if len(argv) != 3:
        print('usage: %s LOGFILE LEVELFILE' % argv[0], file=sys.stderr)
        return 2
    log_path, level_path = argv[1], argv[2]
    records = read_log_file(log_path)
    levels = load_levels(level_path)
    write_json(records, log_path + '.json')
    write_report(records, log_path + '.report.txt', levels)
    skipped = write_unparsed(records, log_path + '.unparsed.txt')
    print('%s: %d records parsed, %d unparsed'
          % (log_path, len(records) - skipped, skipped))
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv))

