import json
import os
import sys

DEFAULT_SEPARATOR = "_"


def flatten_dict(nested_dict, separator):
    flattened_dict = {}
    for key, value in nested_dict.items():
        if isinstance(value, dict):
            for inner_key, inner_value in value.items():
                flattened_dict[f"{key}{separator}{inner_key}"] = inner_value
        else:
            flattened_dict[key] = value
    return flattened_dict


def load_nested(path):
    with open(path, encoding="utf-8") as f:
        data = json.load(f)
    if not isinstance(data, dict):
        raise ValueError(f"{path} must contain a JSON object")
    return data


def read_separator(config_path):
    with open(config_path, encoding="utf-8") as f:
        for line in f:
            name, _, value = line.partition("=")
            if name.strip() == "separator":
                return value.strip().strip('"')
    return DEFAULT_SEPARATOR


def write_json(path, flattened_dict):
    with open(path, "w", encoding="utf-8") as f:
        json.dump(flattened_dict, f, indent=2, sort_keys=True)
        f.write("\n")


def write_properties(path, flattened_dict):
    with open(path, "w", encoding="utf-8") as f:
        for key in sorted(flattened_dict):
            f.write(f"{key}={flattened_dict[key]}\n")


def append_log(log_path, source, count):
    with open(log_path, "a", encoding="utf-8") as f:
        f.write(f"{source}\t{count} keys\n")


def main(argv):
    if len(argv) < 2:
        print("usage: flatten.py INPUT.json [OUTPUT_DIR]", file=sys.stderr)
        return 1
    source = argv[1]
    out_dir = argv[2] if len(argv) > 2 else os.path.dirname(source) or "."
    config_path = os.path.join(out_dir, "flatten.cfg")
    separator = read_separator(config_path) if os.path.isfile(config_path) else DEFAULT_SEPARATOR

    nested = load_nested(source)
    flattened = flatten_dict(nested, separator)

    base = os.path.splitext(os.path.basename(source))[0]
    write_json(os.path.join(out_dir, base + ".flat.json"), flattened)
    write_properties(os.path.join(out_dir, base + ".properties"), flattened)
    append_log(os.path.join(out_dir, "flatten.log"), source, len(flattened))

    for key in sorted(flattened):
        print(f"{key} -> {flattened[key]}")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

