import csv
import os

SAMPLE_TRADES = [
    ("AAPL", 10.0, 12.0, 100),
    ("MSFT", 15.0, 13.0, 50),
    ("TSLA", 220.5, 240.25, 12),
]


def calculate_stock_profit(buy_price, sell_price, quantity):
    if quantity < 0:
        raise ValueError("quantity must not be negative")
    if buy_price < 0 or sell_price < 0:
        raise ValueError("prices must not be negative")
    return round((float(sell_price) - float(buy_price)) * quantity, 2)


def seed_trade_file(path, trades):
    with open(path, "w", newline="", encoding="utf-8") as handle:
        writer = csv.writer(handle)
        writer.writerow(["symbol", "buy_price", "sell_price", "quantity"])
        for symbol, buy_price, sell_price, quantity in trades:
            writer.writerow([symbol, buy_price, sell_price, quantity])


def load_trades(path):
    trades = []
    with open(path, newline="", encoding="utf-8") as handle:
        for row in csv.DictReader(handle):
            trades.append((
                row["symbol"].strip().upper(),
                float(row["buy_price"]),
                float(row["sell_price"]),
                int(row["quantity"]),
            ))
    return trades


def write_trade_report(path, trades):
    with open(path, "w", newline="", encoding="utf-8") as handle:
        writer = csv.writer(handle)
        writer.writerow(["symbol", "quantity", "profit_loss"])
        for symbol, buy_price, sell_price, quantity in trades:
            profit_loss = calculate_stock_profit(buy_price, sell_price, quantity)
            writer.writerow([symbol, quantity, f"{profit_loss:.2f}"])


def summarize_report(path):
    total = 0.0
    winners = 0
    count = 0
    with open(path, newline="", encoding="utf-8") as handle:
        for row in csv.DictReader(handle):
            profit_loss = float(row["profit_loss"])
            total += profit_loss
            count += 1
            if profit_loss > 0:
                winners += 1
    return {"trades": count, "winners": winners, "net": round(total, 2)}


def append_audit_log(path, summary):
    with open(path, "a", encoding="utf-8") as handle:
        handle.write(
            "trades={trades} winners={winners} net={net:+.2f}\n".format(**summary)
        )


def main():
    workdir = "stock_data"
    os.makedirs(workdir, exist_ok=True)
    trade_file = os.path.join(workdir, "trades.csv")
    report_file = os.path.join(workdir, "report.csv")
    log_file = os.path.join(workdir, "audit.log")

    seed_trade_file(trade_file, SAMPLE_TRADES)
    trades = load_trades(trade_file)
    write_trade_report(report_file, trades)

    summary = summarize_report(report_file)
    append_audit_log(log_file, summary)

    for symbol, buy_price, sell_price, quantity in trades:
        print(symbol, calculate_stock_profit(buy_price, sell_price, quantity))
    print("net profit/loss:", summary["net"])


if __name__ == "__main__":
    main()

import os
import sys


def decimal_to_hex(decimal_num):
    if not isinstance(decimal_num, int) or isinstance(decimal_num, bool):
        raise TypeError("decimal_num must be an int")
    digits = "0123456789ABCDEF"
    n = abs(decimal_num)
    if n == 0:
        return "0"
    out = []
    while n:
        out.append(digits[n % 16])
        n //= 16
    sign = "-" if decimal_num < 0 else ""
    return sign + "".join(reversed(out))


def parse_numbers_file(path):
    numbers = []
    errors = []
    with open(path, "r", encoding="utf-8") as src:
        for lineno, line in enumerate(src, start=1):
            token = line.strip()
            if not token or token.startswith("#"):
                continue
            try:
                numbers.append(int(token, 10))
            except ValueError:
                errors.append((lineno, token))
    return numbers, errors


def write_hex_file(path, numbers):
    with open(path, "w", encoding="utf-8") as dst:
        for value in numbers:
            dst.write("{}\t{}\n".format(value, decimal_to_hex(value)))


def write_error_log(path, errors):
    with open(path, "w", encoding="utf-8") as log:
        for lineno, token in errors:
            log.write("line {}: not a decimal integer: {!r}\n".format(lineno, token))


def width_histogram(hex_path):
    histogram = {}
    with open(hex_path, "r", encoding="utf-8") as src:
        for line in src:
            hex_string = line.rstrip("\n").split("\t")[1].lstrip("-")
            histogram[len(hex_string)] = histogram.get(len(hex_string), 0) + 1
    return histogram


def write_report(path, hex_path, error_count):
    histogram = width_histogram(hex_path)
    total = sum(histogram.values())
    with open(path, "w", encoding="utf-8") as report:
        report.write("converted values: {}\n".format(total))
        report.write("rejected lines:   {}\n".format(error_count))
        for width in sorted(histogram):
            report.write("{} hex digit(s): {}\n".format(width, histogram[width]))


def main(argv):
    if len(argv) != 2:
        print("usage: {} NUMBERS_FILE".format(os.path.basename(argv[0])))
        return 2
    source = argv[1]
    stem = os.path.splitext(source)[0]
    hex_path = stem + ".hex.txt"
    report_path = stem + ".report.txt"
    numbers, errors = parse_numbers_file(source)
    write_hex_file(hex_path, numbers)
    if errors:
        write_error_log(stem + ".errors.log", errors)
    write_report(report_path, hex_path, len(errors))
    print("wrote {} and {}".format(hex_path, report_path))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

