import json
import sys
import time


def celsius_to_fahrenheit(celsius):
    return float(celsius) * 9 / 5 + 32


def load_config(path):
    settings = {"report": "report.txt", "summary": "summary.json", "log": "conversions.log"}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            text = line.strip()
            if not text or text.startswith("#"):
                continue
            key, sep, value = text.partition("=")
            if sep and key.strip() in settings:
                settings[key.strip()] = value.strip()
    return settings


def parse_readings(path):
    readings = []
    with open(path, "r", encoding="utf-8") as f:
        for lineno, line in enumerate(f, start=1):
            text = line.strip()
            if not text or text.startswith("#"):
                continue
            label, _, value = text.partition(",")
            try:
                readings.append((label.strip(), float(value)))
            except ValueError:
                sys.stderr.write("skipping bad value on line %d of %s\n" % (lineno, path))
    return readings


def write_report(path, readings):
    with open(path, "w", encoding="utf-8") as f:
        f.write("%-20s %10s %10s\n" % ("station", "celsius", "fahrenheit"))
        for label, celsius in readings:
            f.write("%-20s %10.1f %10.1f\n" % (label, celsius, celsius_to_fahrenheit(celsius)))


def write_summary(path, readings):
    temps = [celsius_to_fahrenheit(c) for _, c in readings]
    summary = {
        "count": len(temps),
        "min_f": min(temps) if temps else None,
        "max_f": max(temps) if temps else None,
        "mean_f": sum(temps) / len(temps) if temps else None,
    }
    with open(path, "w", encoding="utf-8") as f:
        json.dump(summary, f, indent=2, sort_keys=True)
        f.write("\n")
    return summary


def append_log(path, source, summary):
    stamp = time.strftime("%Y-%m-%d %H:%M:%S")
    with open(path, "a", encoding="utf-8") as f:
        f.write("%s %s %d readings\n" % (stamp, source, summary["count"]))


def main(argv):
    if len(argv) < 2:
        sys.stderr.write("usage: %s READINGS.CSV [CONFIG.INI]\n" % argv[0])
        return 2
    source = argv[1]
    settings = load_config(argv[2]) if len(argv) > 2 else None
    if settings is None:
        settings = {"report": "report.txt", "summary": "summary.json", "log": "conversions.log"}
    try:
        readings = parse_readings(source)
    except OSError as exc:
        sys.stderr.write("cannot read %s: %s\n" % (source, exc))
        return 1
    write_report(settings["report"], readings)
    summary = write_summary(settings["summary"], readings)
    append_log(settings["log"], source, summary)
    print("converted %d readings from %s" % (summary["count"], source))
    if summary["count"]:
        print("range: %.1f F to %.1f F" % (summary["min_f"], summary["max_f"]))
        print("mean: %.1f F" % summary["mean_f"])
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

