import sys


def parse_clock(text):
    hours, _, minutes = text.strip().partition(":")
    return int(hours) * 60 + int(minutes)


def format_clock(minutes):
    return "{:02d}:{:02d}".format(minutes // 60, minutes % 60)


def load_config(path):
    bounds = {"day_start": parse_clock("00:00"), "day_end": parse_clock("23:59")}
    with open(path, encoding="utf-8") as handle:
        for line in handle:
            key, sep, value = line.partition("=")
            if sep and key.strip() in bounds:
                bounds[key.strip()] = parse_clock(value)
    return bounds


def load_events(path):
    events = []
    with open(path, encoding="utf-8") as handle:
        for number, line in enumerate(handle, start=1):
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            parts = line.split(",")
            if len(parts) != 3:
                raise ValueError("bad record on line %d: %s" % (number, line))
            name, start, end = parts
            events.append((name.strip(), (parse_clock(start), parse_clock(end))))
    return events


def check_event_overlap(event1, event2):
    start1, end1 = event1
    start2, end2 = event2
    return start1 < end2 and start2 < end1


def find_conflicts(events):
    conflicts = []
    for index, (name1, times1) in enumerate(events):
        for name2, times2 in events[index + 1:]:
            if check_event_overlap(times1, times2):
                conflicts.append((name1, times1, name2, times2))
    return conflicts


def write_report(path, conflicts):
    with open(path, "w", encoding="utf-8") as handle:
        handle.write("conflicting events: %d\n" % len(conflicts))
        for name1, times1, name2, times2 in conflicts:
            handle.write("%s (%s-%s) overlaps %s (%s-%s)\n" % (
                name1, format_clock(times1[0]), format_clock(times1[1]),
                name2, format_clock(times2[0]), format_clock(times2[1])))


def free_slots(events, day_start, day_end):
    busy = sorted(times for _, times in events)
    slots = []
    cursor = day_start
    for start, end in busy:
        if start > cursor:
            slots.append((cursor, min(start, day_end)))
        cursor = max(cursor, end)
    if cursor < day_end:
        slots.append((cursor, day_end))
    return [slot for slot in slots if slot[0] < slot[1]]


def write_free_slots(path, slots):
    with open(path, "w", encoding="utf-8") as handle:
        for start, end in slots:
            handle.write("%s,%s\n" % (format_clock(start), format_clock(end)))


def append_log(path, message):
    with open(path, "a", encoding="utf-8") as handle:
        handle.write(message + "\n")


def main(argv):
    schedule_path = argv[1] if len(argv) > 1 else "schedule.csv"
    config_path = argv[2] if len(argv) > 2 else "schedule.conf"
    bounds = load_config(config_path)
    events = load_events(schedule_path)
    conflicts = find_conflicts(events)
