import sys
from datetime import datetime


def load_jobs(config_path):
    """Each config line holds: <input1> <input2> <output>."""
    jobs = []
    with open(config_path, "r", encoding="utf-8") as f:
        for lineno, line in enumerate(f, start=1):
            stripped = line.strip()
            if not stripped or stripped.startswith("#"):
                continue
            parts = stripped.split()
            if len(parts) != 3:
                raise ValueError(f"{config_path}:{lineno}: expected 3 fields")
            jobs.append(tuple(parts))
    return jobs


def load_sorted_numbers(path):
    """Read whitespace-separated numbers from a file and check they are sorted."""
    numbers = []
    with open(path, "r", encoding="utf-8") as f:
        for lineno, line in enumerate(f, start=1):
            for token in line.split():
                try:
                    numbers.append(float(token) if "." in token else int(token))
                except ValueError:
                    raise ValueError(f"{path}:{lineno}: not a number: {token!r}")
    for i in range(1, len(numbers)):
        if numbers[i - 1] > numbers[i]:
            raise ValueError(f"{path}: not sorted at position {i}")
    return numbers


def write_numbers(path, numbers):
    with open(path, "w", encoding="utf-8") as f:
        for value in numbers:
            f.write(f"{value}\n")


def append_log(path, message):
    with open(path, "a", encoding="utf-8") as f:
        f.write(f"{datetime.now().isoformat(timespec='seconds')} {message}\n")


def write_summary(path, rows):
    with open(path, "w", encoding="utf-8") as f:
        f.write("output\tcount\tmin\tmax\n")
        for name, values in rows:
            low = values[0] if values else "-"
            high = values[-1] if values else "-"
            f.write(f"{name}\t{len(values)}\t{low}\t{high}\n")


def merge_sorted_lists(list1, list2):
    """Merge two sorted lists of numbers into a new sorted list."""
    merged = []
    i = j = 0
    while i < len(list1) and j < len(list2):
        if list1[i] <= list2[j]:
            merged.append(list1[i])
            i += 1
        else:
            merged.append(list2[j])
            j += 1
    merged.extend(list1[i:])
    merged.extend(list2[j:])
    return merged


def main(argv):
    if len(argv) != 4:
        print("usage: merge.py <jobs.txt> <summary.tsv> <run.log>", file=sys.stderr)
        return 1
    rows = []
    for first, second, output in load_jobs(argv[1]):
        merged = merge_sorted_lists(load_sorted_numbers(first),
                                    load_sorted_numbers(second))
        write_numbers(output, merged)
        append_log(argv[3], f"{first} + {second} -> {output} ({len(merged)} values)")
        rows.append((output, merged))
    write_summary(argv[2], rows)
    print(f"merged {len(rows)} pair(s); summary in {argv[2]}")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

