import json
import os
import sys


def calculate_factorial(n):
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    result = 1
    for factor in range(2, n + 1):
        result *= factor
    return result


def load_inputs(path):
    numbers = []
    with open(path, "r", encoding="utf-8") as f:
        for lineno, line in enumerate(f, start=1):
            text = line.strip()
            if not text or text.startswith("#"):
                continue
            try:
                numbers.append(int(text))
            except ValueError:
                raise ValueError("%s line %d: %r is not an integer" % (path, lineno, text))
    return numbers


def load_cache(path):
    if not os.path.exists(path):
        return {}
    with open(path, "r", encoding="utf-8") as f:
        raw = json.load(f)
    return {int(key): int(value) for key, value in raw.items()}


def save_cache(path, cache):
    with open(path, "w", encoding="utf-8") as f:
        json.dump({str(key): str(value) for key, value in sorted(cache.items())}, f, indent=2)


def compute_all(numbers, cache):
    results = []
    for n in numbers:
        if n in cache:
            results.append((n, cache[n], True))
        else:
            value = calculate_factorial(n)
            cache[n] = value
            results.append((n, value, False))
    return results


def write_report(path, results):
    with open(path, "w", encoding="utf-8") as f:
        f.write("%-8s %-6s %s\n" % ("n", "cached", "n!"))
        for n, value, cached in results:
            f.write("%-8d %-6s %d\n" % (n, "yes" if cached else "no", value))


def append_log(path, results):
    fresh = sum(1 for item in results if not item[2])
    with open(path, "a", encoding="utf-8") as f:
        f.write("processed %d values, %d computed, %d from cache\n"
                % (len(results), fresh, len(results) - fresh))


def main(argv):
    if len(argv) != 2:
        print("usage: %s NUMBERS_FILE" % os.path.basename(argv[0]))
        return 1
    numbers = load_inputs(argv[1])
    cache = load_cache("factorial_cache.json")
    results = compute_all(numbers, cache)
    save_cache("factorial_cache.json", cache)
    write_report("factorial_report.txt", results)
    append_log("factorial_run.log", results)
    for n, value, _cached in results:
        print("%d! = %d" % (n, value))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

