import sys

EXPRESSION_PATTERN = re.compile(r"^(\d+)\s*([+-])\s*(\d+)$")


def simple_calculator(expression):
    """Evaluate an addition or subtraction of two positive integers."""
    match = EXPRESSION_PATTERN.match(expression.strip())
    if match is None:
        raise ValueError("unsupported expression: %r" % expression)
    left, operator, right = match.group(1), match.group(2), match.group(3)
    if operator == "+":
        return int(left) + int(right)
    return int(left) - int(right)


def load_expressions(path):
    """Return the non-empty, non-comment lines of an expression file."""
    expressions = []
    with open(path, encoding="utf-8") as handle:
        for line in handle:
            text = line.strip()
            if text and not text.startswith("#"):
                expressions.append(text)
    return expressions


def evaluate_all(expressions):
    """Split expressions into (expression, result) pairs and failures."""
    results = []
    failures = []
    for expression in expressions:
        try:
            results.append((expression, simple_calculator(expression)))
        except ValueError as error:
            failures.append((expression, str(error)))
    return results, failures


def write_results(path, results):
    with open(path, "w", encoding="utf-8") as handle:
        for expression, value in results:
            handle.write("{0} = {1}\n".format(expression, value))


def write_failures(path, failures):
    with open(path, "w", encoding="utf-8") as handle:
        for expression, message in failures:
            handle.write("{0}\t{1}\n".format(expression, message))


def write_summary(path, results_path, failure_count):
    """Build a summary report from the results file written earlier."""
    total = 0
    counted = 0
    with open(results_path, encoding="utf-8") as handle:
        for line in handle:
            total += int(line.rsplit("=", 1)[1])
            counted += 1
    with open(path, "w", encoding="utf-8") as handle:
        handle.write("evaluated: {0}\n".format(counted))
        handle.write("failed: {0}\n".format(failure_count))
        handle.write("sum of results: {0}\n".format(total))


