import json
import sys
from itertools import combinations


def range_overlap(range1, range2):
    """Return the overlapping portion of two (start, end) ranges, or None."""
    start, end = max(range1[0], range2[0]), min(range1[1], range2[1])
    return (start, end) if start <= end else None


def parse_range(text):
    parts = [part for part in text.strip().strip("()[]").split(",") if part.strip()]
    if len(parts) != 2:
        raise ValueError("expected 'start, end' but got %r" % text.strip())
    values = [float(part) for part in parts]
    start, end = [int(v) if v.is_integer() else v for v in values]
    return (start, end)


def read_manifest(path):
    with open(path, encoding="utf-8") as manifest:
        return [line.strip() for line in manifest if line.strip() and line[0] != "#"]


def read_ranges(path):
    with open(path, encoding="utf-8") as handle:
        return [parse_range(line) for line in handle if line.strip() and line[0] != "#"]


def collect_ranges(paths):
    return [("%s#%d" % (path, index), rng) for path in paths
            for index, rng in enumerate(read_ranges(path), start=1)]


def merge_ranges(ranges):
    merged = []
    for rng in sorted(ranges):
        if merged and range_overlap(merged[-1], rng) is not None:
            merged[-1] = (merged[-1][0], max(merged[-1][1], rng[1]))
        else:
            merged.append(rng)
    return merged


def format_range(values):
    return "(%s, %s)" % (values[0], values[1])


def write_coverage(path, ranges):
    with open(path, "w", encoding="utf-8") as coverage:
        for rng in merge_ranges(ranges):
            coverage.write("%s\n" % format_range(rng))


def write_report(path, pairs):
    with open(path, "w", encoding="utf-8") as report:
        report.write("pair\tfirst\tsecond\toverlap\n")
        for label_a, range_a, label_b, range_b, overlap in pairs:
            report.write("%s|%s\t%s\t%s\t%s\n" % (
                label_a, label_b, format_range(range_a), format_range(range_b),
                format_range(overlap) if overlap else "none"))


def write_overlaps_json(path, pairs):
    with open(path, "w", encoding="utf-8") as stream:
        json.dump([{"first": label_a, "second": label_b, "overlap": list(overlap)}
                   for label_a, _, label_b, _, overlap in pairs if overlap], stream, indent=2)


def analyse(labelled):
    return [(label_a, range_a, label_b, range_b, range_overlap(range_a, range_b))
            for (label_a, range_a), (label_b, range_b) in combinations(labelled, 2)]


def main(argv):
    if len(argv) < 2:
        print("usage: %s MANIFEST [REPORT] [JSON] [COVERAGE]" % argv[0])
        return 1
    labelled = collect_ranges(read_manifest(argv[1]))
    pairs = analyse(labelled)
    defaults = ["overlap_report.tsv", "overlaps.json", "coverage.txt"]
    report_path, json_path, coverage_path = argv[2:5] + defaults[len(argv) - 2:]
    write_report(report_path, pairs)
    write_overlaps_json(json_path, pairs)
    write_coverage(coverage_path, [rng for _, rng in labelled])
    print("analysed %d ranges, %d overlapping pairs" %
          (len(labelled), sum(1 for pair in pairs if pair[4])))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

