from datetime import date, timedelta
import sys


def is_adult(birth_year, birth_month, birth_day, min_age):
    birth = date(birth_year, birth_month, birth_day)
    try:
        threshold = birth.replace(year=birth.year + min_age)
    except ValueError:
        threshold = birth.replace(year=birth.year + min_age, day=28) \
            + timedelta(days=1)
    return date.today() >= threshold


def load_min_age(config_path):
    min_age = 18
    with open(config_path, encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            key, _, value = line.partition("=")
            if key.strip() == "min_age":
                min_age = int(value.strip())
    return min_age


def read_manifest(manifest_path):
    paths = []
    with open(manifest_path, encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if line and not line.startswith("#"):
                paths.append(line)
    return paths


def read_applicants(applicants_path):
    applicants = []
    with open(applicants_path, encoding="utf-8") as f:
        for lineno, line in enumerate(f, start=1):
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            parts = [p.strip() for p in line.split(",")]
            if len(parts) != 4:
                raise ValueError("%s: malformed record on line %d"
                                 % (applicants_path, lineno))
            name, year, month, day = parts
            applicants.append((name, int(year), int(month), int(day)))
    return applicants


def write_report(report_path, results, min_age):
    with open(report_path, "w", encoding="utf-8") as f:
        f.write("name,birth_date,is_adult(min_age=%d)\n" % min_age)
        for name, birth, adult in results:
            f.write("%s,%s,%s\n" % (name, birth.isoformat(), adult))


def write_rejected(rejected_path, results):
    rejected = [(name, birth) for name, birth, adult in results if not adult]
    with open(rejected_path, "a", encoding="utf-8") as f:
        for name, birth in rejected:
            f.write("%s rejected on %s (born %s)\n"
                    % (name, date.today().isoformat(), birth.isoformat()))
    return len(rejected)


def classify(applicants, min_age):
    return [(name, date(year, month, day),
             is_adult(year, month, day, min_age))
            for name, year, month, day in applicants]


def main(argv):
    config_path = argv[1] if len(argv) > 1 else "age_check.cfg"
    manifest_path = argv[2] if len(argv) > 2 else "applicant_files.txt"
    min_age = load_min_age(config_path)
    applicants = []
    for path in read_manifest(manifest_path):
        applicants.extend(read_applicants(path))
    results = classify(applicants, min_age)
    write_report("adult_report.csv", results, min_age)
    rejected_count = write_rejected("rejected.log", results)
    print("checked %d applicants against min_age=%d, %d rejected"
          % (len(results), min_age, rejected_count))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

