import json
import os
import sys
from datetime import datetime


def pascals_triangle_row(n):
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    row = [1]
    for k in range(n):
        row.append(row[k] * (n - k) // (k + 1))
    return row


def parse_requests(path):
    requests = []
    with open(path, encoding="utf-8") as f:
        for lineno, line in enumerate(f, start=1):
            text = line.split("#", 1)[0].strip()
            if not text:
                continue
            try:
                requests.append(int(text))
            except ValueError:
                raise ValueError("bad row number on line %d: %r" % (lineno, text))
    return requests


def load_cache(path):
    if not os.path.exists(path):
        return {}
    with open(path, encoding="utf-8") as f:
        raw = json.load(f)
    return {int(key): value for key, value in raw.items()}


def save_cache(path, cache):
    with open(path, "w", encoding="utf-8") as f:
        json.dump({str(key): value for key, value in cache.items()}, f, indent=1)


def format_row(n, row):
    return "row %d: %s" % (n, " ".join(str(value) for value in row))


def write_report(path, results):
    with open(path, "w", encoding="utf-8") as f:
        for n, row in results:
            f.write(format_row(n, row) + "\n")
        f.write("total rows: %d\n" % len(results))


def append_log(path, message):
    with open(path, "a", encoding="utf-8") as f:
        f.write("%s %s\n" % (datetime.now().isoformat(timespec="seconds"), message))


def main(argv):
    if len(argv) < 2:
        print("usage: %s REQUESTS_FILE [CACHE_FILE]" % argv[0])
        return 1
    requests_path = argv[1]
    cache_path = argv[2] if len(argv) > 2 else "pascal_cache.json"
    cache = load_cache(cache_path)
    results = []
    for n in parse_requests(requests_path):
        if n not in cache:
            cache[n] = pascals_triangle_row(n)
        results.append((n, cache[n]))
    save_cache(cache_path, cache)
    write_report("pascal_report.txt", results)
    append_log("pascal.log", "computed %d rows from %s" % (len(results), requests_path))
    for n, row in results:
        print(format_row(n, row))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

