import sys
from collections import Counter


def calculate_mode(data):
    if not data:
        return []
    counts = Counter(data)
    top = max(counts.values())
    return [value for value, count in counts.items() if count == top]


def read_dataset_list(manifest_path):
    paths = []
    with open(manifest_path, "r", encoding="utf-8") as manifest:
        for line in manifest:
            entry = line.strip()
            if entry and not entry.startswith("#"):
                paths.append(entry)
    return paths


def load_numbers(path):
    numbers = []
    with open(path, "r", encoding="utf-8") as source:
        for lineno, line in enumerate(source, start=1):
            text = line.split("#", 1)[0]
            for token in text.replace(",", " ").split():
                try:
                    value = float(token)
                except ValueError:
                    message = "%s:%d: %r is not a number" % (path, lineno, token)
                    raise ValueError(message)
                numbers.append(int(value) if value.is_integer() else value)
    return numbers


def write_frequency_table(path, data):
    counts = Counter(data)
    with open(path + ".freq.csv", "w", encoding="utf-8") as table:
        table.write("value,count\n")
