        lines.append("Mode(s): %s" % ", ".join(str(m) for m in modes))
    else:
        lines.append("Mode(s): none (empty dataset)")
    return "\n".join(lines) + "\n"


def analyse(path):
    data = load_numbers(path)
    modes = sorted(calculate_mode(data))
