import sys


def calculate_sample_std_dev(numbers):
    count = len(numbers)
    if count < 2:
        return 0.0
    mean = sum(numbers) / count
    variance = sum((value - mean) ** 2 for value in numbers) / (count - 1)
    return variance ** 0.5


def read_manifest(path):
    paths = []
    with open(path, "r", encoding="utf-8") as handle:
        for raw in handle:
            entry = raw.strip()
            if entry and not entry.startswith("#"):
                paths.append(entry)
    return paths


def read_series(path):
    series = {}
    errors = []
    with open(path, "r", encoding="utf-8") as handle:
        for line_no, raw in enumerate(handle, start=1):
            line = raw.strip()
            if not line or line.startswith("#"):
                continue
            if ":" not in line:
                errors.append("%s line %d: missing ':' separator" % (path, line_no))
                continue
            name, payload = line.split(":", 1)
            values = []
            for token in payload.replace(",", " ").split():
                try:
                    values.append(float(token))
                except ValueError:
                    errors.append("%s line %d: bad number %r" % (path, line_no, token))
            series[name.strip()] = values
    return series, errors


def read_settings(path):
    settings = {"precision": 6, "min_count": 2}
    with open(path, "r", encoding="utf-8") as handle:
        for raw in handle:
            if "=" in raw:
                key, value = raw.split("=", 1)
                key = key.strip()
                if key in settings:
                    settings[key] = int(value.strip())
    return settings


def write_summary(path, series, settings):
    with open(path, "w", encoding="utf-8") as handle:
        handle.write("name\tcount\tstd_dev\n")
        for name in sorted(series):
            values = series[name]
            if len(values) < settings["min_count"]:
                handle.write("%s\t%d\tskipped\n" % (name, len(values)))
                continue
            std_dev = calculate_sample_std_dev(values)
            handle.write("%s\t%d\t%.*f\n" % (name, len(values), settings["precision"], std_dev))


def write_errors(path, errors):
    with open(path, "w", encoding="utf-8") as handle:
        for message in errors:
            handle.write(message + "\n")


def main(argv):
    if len(argv) != 5:
        print("usage: stddev.py MANIFEST SETTINGS SUMMARY ERRORS")
        return 1
    manifest_path, settings_path, summary_path, errors_path = argv[1:]
    series = {}
    errors = []
    for data_path in read_manifest(manifest_path):
        part, problems = read_series(data_path)
        series.update(part)
        errors.extend(problems)
    settings = read_settings(settings_path)
    write_summary(summary_path, series, settings)
    if errors:
        write_errors(errors_path, errors)
        print("%d problem(s) written to %s" % (len(errors), errors_path))
    print("summary for %d series written to %s" % (len(series), summary_path))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

