import sys


def check_interval_overlap(interval1, interval2):
    start1, end1 = interval1
    start2, end2 = interval2
    return start1 <= end2 and start2 <= end1


def load_config(path):
    config = {}
    with open(path) as f:
        for line in f:
            line = line.strip()
            if line and not line.startswith("#"):
                key, value = line.split("=", 1)
                config[key.strip()] = value.strip()
    return config


def load_intervals(path):
    intervals = []
    with open(path) as f:
        for line in f:
            line = line.strip()
            if line and not line.startswith("#"):
                intervals.append(parse_interval(line))
    return intervals


def write_report(path, intervals, pairs):
    with open(path, "w") as f:
        f.write("intervals: %d\n" % len(intervals))
        f.write("overlapping pairs: %d\n" % len(pairs))
        for i, j in pairs:
            f.write("#%d %s overlaps #%d %s\n"
                    % (i, intervals[i], j, intervals[j]))


def write_cross_report(path, intervals_a, intervals_b, pairs):
    with open(path, "w") as f:
        for i, j in pairs:
            f.write("a#%d %s overlaps b#%d %s\n"
                    % (i, intervals_a[i], j, intervals_b[j]))


def write_merged(path, merged):
    with open(path, "w") as f:
        for start, end in merged:
            f.write("%g %g\n" % (start, end))


def parse_interval(line):
    parts = line.replace(",", " ").split()
    if len(parts) != 2:
        raise ValueError("expected two numbers per interval: %r" % line)
    start, end = (float(p) for p in parts)
    if start > end:
        raise ValueError("start after end in interval: %r" % line)
    return (start, end)


def find_overlapping_pairs(intervals):
    pairs = []
    for i in range(len(intervals)):
        for j in range(i + 1, len(intervals)):
            if check_interval_overlap(intervals[i], intervals[j]):
                pairs.append((i, j))
    return pairs


def find_cross_pairs(intervals_a, intervals_b):
    pairs = []
    for i, first in enumerate(intervals_a):
        for j, second in enumerate(intervals_b):
            if check_interval_overlap(first, second):
                pairs.append((i, j))
    return pairs


def merge_intervals(intervals):
    merged = []
    for interval in sorted(intervals):
        if merged and check_interval_overlap(merged[-1], interval):
            start, end = merged[-1]
            merged[-1] = (start, max(end, interval[1]))
        else:
            merged.append(interval)
    return merged


def main(argv):
    config = load_config(argv[1] if len(argv) > 1 else "schedule.cfg")
    intervals_a = load_intervals(config["input_a"])
    intervals_b = load_intervals(config["input_b"])
    pairs = find_overlapping_pairs(intervals_a)
    cross = find_cross_pairs(intervals_a, intervals_b)
    write_report(config["report"], intervals_a, pairs)
    write_cross_report(config["cross"], intervals_a, intervals_b, cross)
    write_merged(config["merged"], merge_intervals(intervals_a + intervals_b))
    print("%d overlapping pairs, %d cross overlaps" % (len(pairs), len(cross)))
    return 1 if pairs or cross else 0


if __name__ == "__main__":
