import sys


def geometric_series_sum(a, r, n):
    if n < 0:
        raise ValueError("number of terms must be non-negative")
    if r == 1:
        return a * n
    if isinstance(a, float) or isinstance(r, float):
        return a * (1 - r ** n) / (1 - r)
    return a * (1 - r ** n) // (1 - r)


def parse_case(line):
    parts = [p.strip() for p in line.replace(",", " ").split()]
    if len(parts) != 3:
        raise ValueError("expected three values 'a r n', got %r" % line.strip())
    a_text, r_text, n_text = parts
    a = float(a_text) if "." in a_text else int(a_text)
    r = float(r_text) if "." in r_text else int(r_text)
    return a, r, int(n_text)


def load_cases(path):
    cases = []
    with open(path, encoding="utf-8") as f:
        for number, line in enumerate(f, start=1):
            if line.strip() and not line.lstrip().startswith("#"):
                cases.append((number, line))
    return cases


def write_results(path, results):
    with open(path, "w", encoding="utf-8") as f:
        f.write("a\tr\tn\tsum\n")
        for a, r, n, total in results:
            f.write("%s\t%s\t%d\t%s\n" % (a, r, n, total))


def write_errors(path, errors):
    with open(path, "w", encoding="utf-8") as f:
        for message in errors:
            f.write(message + "\n")


def summarize(path):
    with open(path, encoding="utf-8") as f:
        rows = [line.rstrip("\n").split("\t") for line in f][1:]
    grand_total = sum(float(row[3]) for row in rows)
    return len(rows), grand_total


def write_report(path, source, count, grand_total, errors):
    with open(path, "w", encoding="utf-8") as f:
        f.write("geometric series report for %s\n" % source)
        f.write("series computed: %d\n" % count)
        f.write("combined sum: %g\n" % grand_total)
        f.write("rejected cases: %d\n" % len(errors))


def evaluate(cases):
    results = []
    errors = []
    for number, line in cases:
