            a, r, n = parse_case(line)
            results.append((a, r, n, geometric_series_sum(a, r, n)))
        except ValueError as exc:
            errors.append("line %d: %s" % (number, exc))
    return results, errors


def main(argv):
    source = argv[1] if len(argv) > 1 else "series_cases.txt"
    if not os.path.exists(source):
        print("input file not found: %s" % source)
        return 1
    results, errors = evaluate(load_cases(source))
