import os
import sys
from datetime import date, datetime, timedelta


def count_business_days(year, month):
    if month < 1 or month > 12:
        raise ValueError("month must be between 1 and 12")
    day = date(year, month, 1)
    total = 0
    while day.month == month:
        if day.weekday() < 5:
            total += 1
        day += timedelta(days=1)
    return total


def load_holidays(path):
    holidays = set()
    with open(path, encoding="utf-8") as f:
        lines = f.readlines()
    for lineno, line in enumerate(lines, 1):
        text = line.split("#", 1)[0].strip()
        if text:
            try:
                holidays.add(datetime.strptime(text, "%Y-%m-%d").date())
            except ValueError:
                raise ValueError("%s:%d: bad date %r" % (path, lineno, text))
    return holidays


def parse_requests(path):
    requests = []
    with open(path, encoding="utf-8") as f:
        lines = f.readlines()
    for lineno, line in enumerate(lines, 1):
        fields = line.split("#", 1)[0].replace(",", " ").split()
        if fields:
            if len(fields) != 2:
                raise ValueError("%s:%d: expected 'year month'" % (path, lineno))
            requests.append((int(fields[0]), int(fields[1])))
    return requests


def write_report(path, rows):
    with open(path, "w", encoding="utf-8") as f:
        f.write("%-18s %14s %13s\n" % ("Month", "Business", "Working"))
        for label, business, working in rows:
            f.write("%-18s %14d %13d\n" % (label, business, working))


def write_csv(path, rows):
    with open(path, "w", encoding="utf-8") as f:
        f.write("month,business_days,working_days\n")
        for label, business, working in rows:
            f.write("%s,%d,%d\n" % (label, business, working))


def append_log(path, rows):
    stamp = datetime.now().isoformat(timespec="seconds")
    total = sum(row[1] for row in rows)
    with open(path, "a", encoding="utf-8") as f:
        f.write("%s  %d period(s), %d business days\n" % (stamp, len(rows), total))


def count_working_days(year, month, holidays):
    off = 0
    for holiday in holidays:
        if holiday.year == year and holiday.month == month and holiday.weekday() < 5:
            off += 1
    return count_business_days(year, month) - off


def build_rows(requests, holidays):
    rows = []
    for year, month in requests:
        label = date(year, month, 1).strftime("%B %Y")
        rows.append((label, count_business_days(year, month),
                     count_working_days(year, month, holidays)))
    return rows


def main(argv):
    requests_path = argv[1] if len(argv) > 1 else "requests.txt"
    holidays_path = argv[2] if len(argv) > 2 else "holidays.txt"
    holidays = set()
    if os.path.exists(holidays_path):
        holidays = load_holidays(holidays_path)
    rows = build_rows(parse_requests(requests_path), holidays)
    write_report("report.txt", rows)
    write_csv("report.csv", rows)
    append_log("business_days.log", rows)
    for label, business, working in rows:
        print("%s: %d business days, %d working days" % (label, business, working))


if __name__ == "__main__":
    main(sys.argv)

