import argparse
import os
import sys

ALPHABET_SIZE = 26


def caesar_encrypt(text, shift):
    result = []
    for char in text:
        if 'a' <= char <= 'z':
            base = ord('a')
        elif 'A' <= char <= 'Z':
            base = ord('A')
        else:
            result.append(char)
            continue
        offset = (ord(char) - base + shift) % ALPHABET_SIZE
        result.append(chr(base + offset))
    return ''.join(result)


def caesar_decrypt(text, shift):
    return caesar_encrypt(text, -shift)


def load_shift(path, default=3):
    """Read the shift value from a one-line configuration file."""
    if not os.path.exists(path):
        return default
    with open(path, encoding='utf-8') as config:
        raw = config.read().strip()
    if not raw.lstrip('+-').isdigit():
        raise ValueError('invalid shift in {}: {!r}'.format(path, raw))
    return int(raw)


def encrypt_file(src, dst, shift):
    """Encrypt src into dst and report the plain text and its length."""
    with open(src, encoding='utf-8') as source:
        plain = source.read()
    cipher = caesar_encrypt(plain, shift)
    with open(dst, 'w', encoding='utf-8') as target:
        target.write(cipher)
    return plain, len(cipher)


def decrypt_file(src, dst, shift):
    with open(src, encoding='utf-8') as source:
        cipher = source.read()
    plain = caesar_decrypt(cipher, shift)
    with open(dst, 'w', encoding='utf-8') as target:
        target.write(plain)
    return plain


def write_report(path, entries):
    with open(path, 'w', encoding='utf-8') as report:
        report.write('file\tchars\tround_trip\n')
        for name, size, ok in entries:
            report.write('{}\t{}\t{}\n'.format(name, size, 'yes' if ok else 'no'))


def main(argv=None):
    parser = argparse.ArgumentParser(description='Caesar-encrypt text files.')
    parser.add_argument('files', nargs='+')
    parser.add_argument('--config', default='caesar.cfg')
    parser.add_argument('--report', default='caesar_report.tsv')
    args = parser.parse_args(argv)

    shift = load_shift(args.config)
    entries = []
    for name in args.files:
        plain, size = encrypt_file(name, name + '.enc', shift)
        restored = decrypt_file(name + '.enc', name + '.dec', shift)
        entries.append((name, size, restored == plain))
    write_report(args.report, entries)
    print('processed {} file(s) with shift {}'.format(len(entries), shift))
    return 0


if __name__ == '__main__':
    sys.exit(main())

import csv
import sys


def load_aliases(path):
    """Read `canonical,alias` pairs used to merge duplicate movie titles."""
    aliases = {}
    with open(path, newline="", encoding="utf-8") as f:
        for row in csv.reader(f):
            if len(row) >= 2:
                aliases[row[1].strip()] = row[0].strip()
    return aliases


def load_ratings(path, aliases):
    """Read a CSV file of `title,rating,rating,...` rows into a dictionary."""
    ratings = {}
    with open(path, newline="", encoding="utf-8") as f:
        for row in csv.reader(f):
            if not row:
                continue
            title = row[0].strip()
            values = ratings.setdefault(aliases.get(title, title), [])
            for cell in row[1:]:
                cell = cell.strip()
                if cell:
                    values.append(float(cell))
    return ratings


def load_catalog(path, aliases):
    """Read the released movie titles, one per line."""
    titles = []
    with open(path, encoding="utf-8") as f:
        for line in f:
            title = line.strip()
            if title:
                titles.append(aliases.get(title, title))
    return titles


def write_averages_csv(path, averages):
    with open(path, "w", newline="", encoding="utf-8") as f:
        writer = csv.writer(f)
        writer.writerow(["title", "average_rating"])
        for title in sorted(averages):
            writer.writerow([title, "{:.3f}".format(averages[title])])


def write_report(path, movie_ratings, averages):
    ranked = sorted(averages.items(), key=lambda item: (-item[1], item[0]))
    with open(path, "w", encoding="utf-8") as f:
        f.write("Movie rating report\n")
        f.write("===================\n")
        for title, average in ranked:
            count = len(movie_ratings[title])
            if count:
                f.write("{:<30} {:.2f} ({} ratings)\n".format(title, average, count))
            else:
                f.write("{:<30} {:.2f} (unrated)\n".format(title, average))
        rated = [a for t, a in ranked if movie_ratings[t]]
        if rated:
            f.write("\nMean of rated movies: {:.3f}\n".format(sum(rated) / len(rated)))


def get_average_movie_rating(movie_ratings):
    """Return each movie's average rating, or 0.0 when it has no ratings."""
    return {t: sum(r) / len(r) if r else 0.0 for t, r in movie_ratings.items()}


def main(argv):
    if len(argv) != 6:
        print("usage: ratings.py ALIASES.csv RATINGS.csv CATALOG.txt OUT.csv REPORT.txt")
        return 1
    alias_path, ratings_path, catalog_path, csv_path, report_path = argv[1:]
    aliases = load_aliases(alias_path)
    movie_ratings = load_ratings(ratings_path, aliases)
    for title in load_catalog(catalog_path, aliases):
        movie_ratings.setdefault(title, [])
    averages = get_average_movie_rating(movie_ratings)
    write_averages_csv(csv_path, averages)
    write_report(report_path, movie_ratings, averages)
    print("Processed {} movies".format(len(averages)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

